import numpy as np

def softmax_with_temperature(logits, temperature):
    logits = np.asarray(logits, dtype=float)
    scaled = logits / max(temperature, 1e-6)
    e = np.exp(scaled - np.max(scaled))
    return e / np.sum(e)

