import numpy as np

def dropout_forward(x, keep_prob, training=True, seed=None):
    if not training or keep_prob >= 1.0:
        return x, None
    rng = np.random.default_rng(seed)
    mask = (rng.random(x.shape) < keep_prob) / keep_prob
    return x * mask, mask

def dropout_backward(grad, mask):
    if mask is None:
        return grad
    return grad * mask
